CREATE TABLE organization (id BIGSERIAL PRIMARY KEY, name VARCHAR(150) NOT NULL UNIQUE, description TEXT, default_latitude NUMERIC(10,7), default_longitude NUMERIC(10,7), default_zoom INT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE app_user (id BIGSERIAL PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, display_name VARCHAR(150) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE organization_member (id BIGSERIAL PRIMARY KEY, organization_id BIGINT NOT NULL REFERENCES organization(id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, role VARCHAR(30) NOT NULL, created_at TIMESTAMPTZ NOT NULL, UNIQUE(organization_id,user_id));
CREATE TABLE community_map (id BIGSERIAL PRIMARY KEY, organization_id BIGINT NOT NULL REFERENCES organization(id) ON DELETE CASCADE, name VARCHAR(150) NOT NULL, description TEXT, visibility VARCHAR(30) NOT NULL, center_latitude NUMERIC(10,7), center_longitude NUMERIC(10,7), default_zoom INT NOT NULL DEFAULT 12, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE category (id BIGSERIAL PRIMARY KEY, map_id BIGINT NOT NULL REFERENCES community_map(id) ON DELETE CASCADE, name VARCHAR(100) NOT NULL, description TEXT, color VARCHAR(20), icon VARCHAR(50), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, UNIQUE(map_id,name));
CREATE TABLE status_definition (id BIGSERIAL PRIMARY KEY, map_id BIGINT NOT NULL REFERENCES community_map(id) ON DELETE CASCADE, name VARCHAR(80) NOT NULL, display_order INT NOT NULL DEFAULT 0, terminal BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(map_id,name));
CREATE TABLE custom_field_definition (id BIGSERIAL PRIMARY KEY, category_id BIGINT NOT NULL REFERENCES category(id) ON DELETE CASCADE, name VARCHAR(80) NOT NULL, label VARCHAR(120) NOT NULL, field_type VARCHAR(30) NOT NULL, required BOOLEAN NOT NULL DEFAULT FALSE, options_json TEXT, display_order INT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE map_item (id BIGSERIAL PRIMARY KEY, map_id BIGINT NOT NULL REFERENCES community_map(id) ON DELETE CASCADE, category_id BIGINT NOT NULL REFERENCES category(id), status_id BIGINT REFERENCES status_definition(id), title VARCHAR(180) NOT NULL, description TEXT, latitude NUMERIC(10,7) NOT NULL, longitude NUMERIC(10,7) NOT NULL, address VARCHAR(255), created_by BIGINT REFERENCES app_user(id), updated_by BIGINT REFERENCES app_user(id), created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE custom_field_value (id BIGSERIAL PRIMARY KEY, map_item_id BIGINT NOT NULL REFERENCES map_item(id) ON DELETE CASCADE, field_definition_id BIGINT NOT NULL REFERENCES custom_field_definition(id) ON DELETE CASCADE, value TEXT, UNIQUE(map_item_id,field_definition_id));
CREATE TABLE observation (id BIGSERIAL PRIMARY KEY, map_item_id BIGINT NOT NULL REFERENCES map_item(id) ON DELETE CASCADE, title VARCHAR(180), description TEXT NOT NULL, observed_at TIMESTAMPTZ NOT NULL, created_by BIGINT REFERENCES app_user(id), created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE photo (id BIGSERIAL PRIMARY KEY, map_item_id BIGINT REFERENCES map_item(id) ON DELETE CASCADE, observation_id BIGINT REFERENCES observation(id) ON DELETE CASCADE, storage_key VARCHAR(500) NOT NULL, file_name VARCHAR(255), content_type VARCHAR(120), uploaded_by BIGINT REFERENCES app_user(id), created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE source_link (id BIGSERIAL PRIMARY KEY, map_item_id BIGINT NOT NULL REFERENCES map_item(id) ON DELETE CASCADE, label VARCHAR(150), url TEXT NOT NULL, created_by BIGINT REFERENCES app_user(id), created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE activity_log (id BIGSERIAL PRIMARY KEY, organization_id BIGINT NOT NULL REFERENCES organization(id) ON DELETE CASCADE, map_id BIGINT REFERENCES community_map(id) ON DELETE CASCADE, map_item_id BIGINT REFERENCES map_item(id) ON DELETE CASCADE, actor_user_id BIGINT REFERENCES app_user(id), activity_type VARCHAR(50) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT, summary VARCHAR(255), details_json TEXT, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_map_item_map ON map_item(map_id); CREATE INDEX idx_observation_item ON observation(map_item_id); CREATE INDEX idx_category_map ON category(map_id);
